{"code": "const res = await tools.bash({
  description: "Parse order JSON files and compute totals",
  command: `node -e '
const fs=require("fs");
const files=fs.readdirSync("orders").filter(f=>f.endsWith(".json")).sort();
const totals={}; const malformed=[];
for(const f of files){
  let o;
